CREATE FUNCTION builder.admit_source_revision(p_account_id uuid, p_project_id uuid, p_source_revision text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE
  latest_code_changing record;
BEGIN
  IF p_source_revision !~ '^[0-9a-f]{40}$' THEN RETURN false; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM iam.visible_projects(p_account_id) AS visible
    WHERE visible.project_id = p_project_id
  ) THEN RETURN false; END IF;
  IF EXISTS (
    SELECT 1 FROM builder.project_working_state AS working
    WHERE working.project_id = p_project_id
      AND (working.working_source_revision = p_source_revision
        OR working.last_preview_source_revision = p_source_revision)
  ) THEN RETURN true; END IF;
  SELECT run.base_source_revision, run.result_source_revision
  INTO latest_code_changing
  FROM builder.builder_run AS run
  WHERE run.project_id = p_project_id
    AND run.result_kind IN ('SOURCE_CHANGED', 'SOURCE_CHANGED_BUILD_FAILED')
    AND run.result_source_revision IS NOT NULL
  ORDER BY run.created_at DESC, run.builder_run_id DESC
  LIMIT 1;
  IF FOUND AND (latest_code_changing.base_source_revision = p_source_revision
    OR latest_code_changing.result_source_revision = p_source_revision) THEN RETURN true; END IF;
  RETURN false;
END;
$_$;

ALTER FUNCTION builder.admit_source_revision(p_account_id uuid, p_project_id uuid, p_source_revision text) OWNER TO builder_owner;

CREATE FUNCTION builder.admit_verified_application_source(p_account_id uuid, p_project_id uuid, p_execution_id uuid, p_source_revision text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1
    FROM builder.builder_run AS run
    JOIN builder.project_working_state AS working ON working.project_id = run.project_id
    WHERE run.builder_run_id = p_execution_id
      AND run.account_id = p_account_id
      AND run.project_id = p_project_id
      AND run.state = 'RUNNING'
      AND run.mode = 'BUILD'
      AND run.result_source_revision = p_source_revision
      AND working.working_source_revision = p_source_revision
  );
END;
$$;

ALTER FUNCTION builder.admit_verified_application_source(p_account_id uuid, p_project_id uuid, p_execution_id uuid, p_source_revision text) OWNER TO builder_owner;

CREATE FUNCTION builder.advance_builder_run_source(p_builder_run_id uuid, p_source_revision text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE run_row builder.builder_run%ROWTYPE; working builder.project_working_state%ROWTYPE;
BEGIN
  IF p_source_revision IS NULL OR p_source_revision !~ '^[0-9a-f]{40}$' THEN RETURN false; END IF;
  SELECT * INTO run_row FROM builder.builder_run WHERE builder_run_id = p_builder_run_id FOR UPDATE;
  IF NOT FOUND OR run_row.state <> 'RUNNING' OR run_row.mode <> 'BUILD' THEN RETURN false; END IF;
  SELECT * INTO working FROM builder.project_working_state WHERE project_id = run_row.project_id FOR UPDATE;
  IF NOT FOUND OR working.working_source_revision <> run_row.base_source_revision
    OR working.working_version <> run_row.base_working_version THEN RETURN false; END IF;
  UPDATE builder.project_working_state
  SET working_source_revision = p_source_revision, working_version = working_version + 1,
      updated_at = clock_timestamp()
  WHERE project_id = run_row.project_id AND working_version = run_row.base_working_version;
  IF NOT FOUND THEN RETURN false; END IF;
  UPDATE builder.builder_run SET result_source_revision = p_source_revision WHERE builder_run_id = p_builder_run_id;
  RETURN true;
END;
$_$;

ALTER FUNCTION builder.advance_builder_run_source(p_builder_run_id uuid, p_source_revision text) OWNER TO builder_owner;

CREATE FUNCTION builder.bind_builder_run_message(p_builder_run_id uuid, p_message_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF p_message_id IS NULL OR length(btrim(p_message_id)) NOT BETWEEN 1 AND 200 THEN RETURN false; END IF;
  UPDATE builder.builder_run SET trigger_message_id = btrim(p_message_id)
  WHERE builder_run_id = p_builder_run_id AND state IN ('QUEUED', 'RUNNING')
    AND (trigger_message_id IS NULL OR trigger_message_id = btrim(p_message_id));
  RETURN FOUND;
END;
$$;

ALTER FUNCTION builder.bind_builder_run_message(p_builder_run_id uuid, p_message_id text) OWNER TO builder_owner;

CREATE FUNCTION builder.bind_builder_run_sandbox(p_builder_run_id uuid, p_sandbox_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF p_sandbox_id IS NULL OR length(btrim(p_sandbox_id)) NOT BETWEEN 1 AND 200 THEN RETURN false; END IF;
  UPDATE builder.builder_run SET sandbox_id = btrim(p_sandbox_id)
  WHERE builder_run_id = p_builder_run_id AND state = 'RUNNING'
    AND (sandbox_id IS NULL OR sandbox_id = btrim(p_sandbox_id));
  RETURN FOUND;
END;
$$;

ALTER FUNCTION builder.bind_builder_run_sandbox(p_builder_run_id uuid, p_sandbox_id text) OWNER TO builder_owner;

CREATE FUNCTION builder.claim_builder_run(p_builder_run_id uuid, p_admission_id text, p_provider_id text, p_model_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE run_row builder.builder_run%ROWTYPE; working builder.project_working_state%ROWTYPE;
BEGIN
  SELECT * INTO run_row FROM builder.builder_run WHERE builder_run_id = p_builder_run_id FOR UPDATE;
  IF NOT FOUND OR run_row.state <> 'QUEUED' THEN RAISE EXCEPTION 'BUILDER_RUN_CLAIM_REFUSED'; END IF;
  PERFORM iam.admit_project(run_row.account_id, run_row.project_id, 'project.build');
  SELECT * INTO working FROM builder.project_working_state WHERE project_id = run_row.project_id FOR UPDATE;
  IF NOT FOUND OR working.working_source_revision <> run_row.base_source_revision OR working.working_version <> run_row.base_working_version THEN RAISE EXCEPTION 'BUILDER_RUN_BASE_STALE'; END IF;
  IF run_row.model_admission_id IS NOT NULL AND (
    run_row.model_admission_id <> p_admission_id OR run_row.model_provider_id <> p_provider_id OR run_row.model_id <> p_model_id
  ) THEN RAISE EXCEPTION 'BUILDER_MODEL_ADMISSION_CONFLICT'; END IF;
  UPDATE builder.builder_run SET state = 'RUNNING', phase = 'PREPARING', started_at = clock_timestamp(),
    model_admission_id = p_admission_id, model_provider_id = p_provider_id, model_id = p_model_id
  WHERE builder_run_id = p_builder_run_id AND state = 'QUEUED';
  IF NOT FOUND THEN RAISE EXCEPTION 'BUILDER_RUN_CLAIM_REFUSED'; END IF;
  SELECT * INTO run_row FROM builder.builder_run WHERE builder_run_id = p_builder_run_id;
  RETURN jsonb_build_object(
    'builderRunId', run_row.builder_run_id, 'projectId', run_row.project_id,
    'state', run_row.state, 'phase', run_row.phase, 'mode', run_row.mode,
    'baseSourceRevision', run_row.base_source_revision,
    'resultSourceRevision', NULL, 'resultKind', NULL, 'failureCode', NULL,
    'modelAdmissionId', run_row.model_admission_id, 'modelProviderId', run_row.model_provider_id,
    'modelId', run_row.model_id, 'modelConnectionId', run_row.model_connection_id,
    'modelCredentialGeneration', run_row.model_credential_generation,
    'cancellationRequested', false
  );
END;
$$;

ALTER FUNCTION builder.claim_builder_run(p_builder_run_id uuid, p_admission_id text, p_provider_id text, p_model_id text) OWNER TO builder_owner;

CREATE FUNCTION builder.clear_builder_run_phase() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NEW.state <> 'RUNNING' OR NEW.cancellation_requested_at IS NOT NULL THEN
    NEW.phase := NULL;
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION builder.clear_builder_run_phase() OWNER TO builder_owner;

CREATE FUNCTION builder.create_builder_run(p_account_id uuid, p_project_id uuid, p_idempotency_digest text, p_request_digest text, p_trigger_message_id text, p_mode text, p_builder_run_id uuid, p_provider_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE working builder.project_working_state%ROWTYPE; existing builder.builder_run%ROWTYPE;
  selected_connection_id uuid; selected_generation bigint;
BEGIN
  PERFORM iam.admit_project(p_account_id, p_project_id, 'project.build');
  IF p_mode NOT IN ('BUILD', 'PLAN') OR p_idempotency_digest !~ '^[0-9a-f]{64}$' OR p_request_digest !~ '^[0-9a-f]{64}$'
    OR (p_trigger_message_id IS NOT NULL AND length(btrim(p_trigger_message_id)) NOT BETWEEN 1 AND 200) THEN RAISE EXCEPTION 'BUILDER_RUN_INPUT_REFUSED'; END IF;
  SELECT * INTO existing FROM builder.builder_run WHERE project_id = p_project_id AND idempotency_digest = p_idempotency_digest;
  IF FOUND THEN
    IF existing.account_id <> p_account_id OR existing.mode <> p_mode OR existing.request_digest <> p_request_digest THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF;
    RETURN jsonb_build_object('builderRunId', existing.builder_run_id, 'projectId', existing.project_id, 'state', existing.state, 'phase', existing.phase, 'mode', existing.mode, 'baseSourceRevision', existing.base_source_revision, 'resultSourceRevision', existing.result_source_revision, 'resultKind', existing.result_kind, 'failureCode', existing.failure_code, 'modelConnectionId', existing.model_connection_id, 'modelCredentialGeneration', existing.model_credential_generation);
  END IF;
  SELECT * INTO working FROM builder.project_working_state WHERE project_id = p_project_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'BUILDER_SUBJECT_NOT_FOUND'; END IF;
  SELECT * INTO existing FROM builder.builder_run WHERE project_id = p_project_id AND idempotency_digest = p_idempotency_digest;
  IF FOUND THEN
    IF existing.account_id <> p_account_id OR existing.mode <> p_mode OR existing.request_digest <> p_request_digest THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF;
    RETURN jsonb_build_object('builderRunId', existing.builder_run_id, 'projectId', existing.project_id, 'state', existing.state, 'phase', existing.phase, 'mode', existing.mode, 'baseSourceRevision', existing.base_source_revision, 'resultSourceRevision', existing.result_source_revision, 'resultKind', existing.result_kind, 'failureCode', existing.failure_code, 'modelConnectionId', existing.model_connection_id, 'modelCredentialGeneration', existing.model_credential_generation);
  END IF;
  IF EXISTS (SELECT 1 FROM builder.builder_run WHERE project_id = p_project_id AND state IN ('QUEUED', 'RUNNING')) THEN RAISE EXCEPTION 'PROJECT_BUSY'; END IF;
  SELECT admitted.connection_id, admitted.generation
  INTO selected_connection_id, selected_generation
  FROM model_connection.admit_for_project(p_account_id, p_project_id, p_provider_id) AS admitted;
  INSERT INTO builder.builder_run(builder_run_id, project_id, account_id, trigger_message_id, idempotency_digest, request_digest, mode, base_source_revision, expected_working_version, base_working_version, model_connection_id, model_credential_generation)
  VALUES (p_builder_run_id, p_project_id, p_account_id, NULLIF(btrim(p_trigger_message_id), ''), p_idempotency_digest, p_request_digest, p_mode, working.working_source_revision, working.working_version, working.working_version, selected_connection_id, selected_generation)
  RETURNING * INTO existing;
  RETURN jsonb_build_object('builderRunId', existing.builder_run_id, 'projectId', existing.project_id, 'state', existing.state, 'phase', existing.phase, 'mode', existing.mode, 'baseSourceRevision', existing.base_source_revision, 'resultSourceRevision', NULL, 'resultKind', NULL, 'failureCode', NULL, 'modelConnectionId', existing.model_connection_id, 'modelCredentialGeneration', existing.model_credential_generation);
END;
$_$;

ALTER FUNCTION builder.create_builder_run(p_account_id uuid, p_project_id uuid, p_idempotency_digest text, p_request_digest text, p_trigger_message_id text, p_mode text, p_builder_run_id uuid, p_provider_id text) OWNER TO builder_owner;

CREATE FUNCTION builder.create_builder_run_with_model(p_account_id uuid, p_project_id uuid, p_idempotency_digest text, p_request_digest text, p_trigger_message_id text, p_mode text, p_builder_run_id uuid, p_admission_id text, p_provider_id text, p_model_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE created jsonb; run_id uuid; run_row builder.builder_run%ROWTYPE; credential_provider_id text;
BEGIN
  IF p_admission_id IS NULL OR p_admission_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$'
    OR p_provider_id IS NULL OR p_provider_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$'
    OR p_model_id IS NULL OR p_model_id !~ '\S' OR p_model_id ~ 'latest|\*' THEN
    RAISE EXCEPTION 'BUILDER_MODEL_ADMISSION_REFUSED';
  END IF;
  created := builder.create_builder_run(
    p_account_id, p_project_id, p_idempotency_digest, p_request_digest,
    p_trigger_message_id, p_mode, p_builder_run_id, p_provider_id
  );
  IF created->>'modelConnectionId' IS NULL OR created->>'modelCredentialGeneration' IS NULL THEN
    RAISE EXCEPTION 'MODEL_CONNECTION_REQUIRED';
  END IF;
  run_id := (created->>'builderRunId')::uuid;
  SELECT credential.provider_id INTO credential_provider_id
  FROM builder.builder_run AS run
  CROSS JOIN LATERAL model_connection.read_connection_credential(run.model_connection_id) AS credential
  WHERE run.builder_run_id = run_id;
  IF credential_provider_id IS DISTINCT FROM p_provider_id THEN
    RAISE EXCEPTION 'MODEL_CONNECTION_PROVIDER_MISMATCH';
  END IF;
  SELECT * INTO run_row FROM builder.builder_run WHERE builder_run_id = run_id FOR UPDATE;
  IF run_row.model_admission_id IS NOT NULL AND (
    run_row.model_admission_id <> p_admission_id OR run_row.model_provider_id <> p_provider_id OR run_row.model_id <> p_model_id
  ) THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF;
  UPDATE builder.builder_run
  SET model_admission_id = p_admission_id, model_provider_id = p_provider_id, model_id = p_model_id
  WHERE builder_run_id = run_id AND model_admission_id IS NULL;
  SELECT * INTO run_row FROM builder.builder_run WHERE builder_run_id = run_id;
  RETURN jsonb_build_object(
    'builderRunId', run_row.builder_run_id, 'projectId', run_row.project_id,
    'state', run_row.state, 'phase', run_row.phase, 'mode', run_row.mode,
    'baseSourceRevision', run_row.base_source_revision,
    'resultSourceRevision', run_row.result_source_revision, 'resultKind', run_row.result_kind,
    'failureCode', run_row.failure_code, 'modelAdmissionId', run_row.model_admission_id,
    'modelProviderId', run_row.model_provider_id, 'modelId', run_row.model_id,
    'modelConnectionId', run_row.model_connection_id,
    'modelCredentialGeneration', run_row.model_credential_generation,
    'cancellationRequested', false
  );
END;
$_$;

ALTER FUNCTION builder.create_builder_run_with_model(p_account_id uuid, p_project_id uuid, p_idempotency_digest text, p_request_digest text, p_trigger_message_id text, p_mode text, p_builder_run_id uuid, p_admission_id text, p_provider_id text, p_model_id text) OWNER TO builder_owner;

CREATE FUNCTION builder.fail_builder_run(p_builder_run_id uuid, p_failure_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
BEGIN
  IF p_failure_code IS NULL OR p_failure_code !~ '^[A-Z0-9_]{1,120}$' THEN RETURN false; END IF;
  UPDATE builder.builder_run SET state = 'FAILED', failure_code = p_failure_code,
    finished_at = clock_timestamp()
  WHERE builder_run_id = p_builder_run_id AND state IN ('QUEUED', 'RUNNING');
  RETURN FOUND;
END;
$_$;

ALTER FUNCTION builder.fail_builder_run(p_builder_run_id uuid, p_failure_code text) OWNER TO builder_owner;

CREATE FUNCTION builder.interrupt_builder_run(p_builder_run_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
BEGIN
  IF p_reason IS NULL OR p_reason !~ '^[A-Z0-9_]{1,120}$' THEN RETURN false; END IF;
  UPDATE builder.builder_run
  SET state = 'INTERRUPTED', failure_code = p_reason,
    cancellation_requested_at = COALESCE(cancellation_requested_at, clock_timestamp()),
    cancellation_reason = COALESCE(cancellation_reason, p_reason), finished_at = clock_timestamp()
  WHERE builder_run_id = p_builder_run_id AND state IN ('QUEUED', 'RUNNING');
  RETURN FOUND;
END;
$_$;

ALTER FUNCTION builder.interrupt_builder_run(p_builder_run_id uuid, p_reason text) OWNER TO builder_owner;

CREATE FUNCTION builder.list_builder_runs(p_account_id uuid, p_project_id uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM iam.visible_projects(p_account_id) AS visible
    WHERE visible.project_id = p_project_id
  ) THEN RETURN '[]'::jsonb; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'builderRunId', run.builder_run_id, 'projectId', run.project_id,
    'state', run.state, 'phase', run.phase, 'mode', run.mode, 'baseSourceRevision', run.base_source_revision,
    'resultSourceRevision', run.result_source_revision, 'resultKind', run.result_kind,
    'failureCode', run.failure_code, 'modelAdmissionId', run.model_admission_id,
    'modelProviderId', run.model_provider_id, 'modelId', run.model_id,
    'cancellationRequested', COALESCE(run.cancellation_requested_at IS NOT NULL, false)
    ) ORDER BY run.created_at DESC), '[]'::jsonb)
  INTO result
  FROM (
    SELECT * FROM builder.builder_run
    WHERE account_id = p_account_id AND project_id = p_project_id
    ORDER BY created_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 50)
  ) AS run;
  RETURN result;
END;
$$;

ALTER FUNCTION builder.list_builder_runs(p_account_id uuid, p_project_id uuid, p_limit integer) OWNER TO builder_owner;

CREATE FUNCTION builder.read_builder_run(p_account_id uuid, p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'builderRunId', run.builder_run_id, 'projectId', run.project_id,
    'state', run.state, 'phase', run.phase, 'mode', run.mode, 'baseSourceRevision', run.base_source_revision,
    'resultSourceRevision', run.result_source_revision, 'resultKind', run.result_kind,
    'failureCode', run.failure_code, 'modelAdmissionId', run.model_admission_id,
    'modelProviderId', run.model_provider_id, 'modelId', run.model_id,
    'cancellationRequested', COALESCE(run.cancellation_requested_at IS NOT NULL, false),
    'modelConnectionId', run.model_connection_id,
    'modelCredentialGeneration', run.model_credential_generation
  )
  FROM builder.builder_run AS run
  JOIN iam.visible_projects(p_account_id) AS visible ON visible.project_id = run.project_id
  WHERE run.project_id = p_project_id
  ORDER BY run.created_at DESC LIMIT 1;
$$;

ALTER FUNCTION builder.read_builder_run(p_account_id uuid, p_project_id uuid) OWNER TO builder_owner;

CREATE FUNCTION builder.read_latest_code_changing_builder_run(p_account_id uuid, p_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  latest_code_changing builder.builder_run%ROWTYPE;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM iam.visible_projects(p_account_id) AS visible
    WHERE visible.project_id = p_project_id
  ) THEN RETURN NULL; END IF;

  SELECT run.* INTO latest_code_changing
  FROM builder.builder_run AS run
  WHERE run.project_id = p_project_id
    AND run.result_kind IN ('SOURCE_CHANGED', 'SOURCE_CHANGED_BUILD_FAILED')
    AND run.result_source_revision IS NOT NULL
  ORDER BY run.created_at DESC, run.builder_run_id DESC
  LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;

  RETURN jsonb_build_object(
    'builderRunId', latest_code_changing.builder_run_id,
    'projectId', latest_code_changing.project_id,
    'baseSourceRevision', latest_code_changing.base_source_revision,
    'resultSourceRevision', latest_code_changing.result_source_revision,
    'resultKind', latest_code_changing.result_kind
  );
END;
$$;

ALTER FUNCTION builder.read_latest_code_changing_builder_run(p_account_id uuid, p_project_id uuid) OWNER TO builder_owner;

CREATE FUNCTION builder.read_preview_subject(p_account_id uuid, p_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  working record;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM iam.visible_projects(p_account_id) AS visible
    WHERE visible.project_id = p_project_id
  ) THEN RETURN NULL; END IF;
  SELECT working_source_revision, last_preview_source_revision,
    last_preview_artifact_revision_id, last_preview_artifact_digest
  INTO working
  FROM builder.project_working_state
  WHERE project_id = p_project_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN jsonb_build_object(
    'subjectKind', 'CURRENT_PROJECT',
    'subjectDigest', working.working_source_revision,
    'sourceRevision', working.working_source_revision,
    'verified', false,
    'previewEligible', working.last_preview_source_revision = working.working_source_revision
      AND working.last_preview_artifact_revision_id IS NOT NULL
      AND working.last_preview_artifact_digest IS NOT NULL,
    'workingSourceRevision', working.working_source_revision,
    'lastPreviewSourceRevision', working.last_preview_source_revision,
    'lastPreviewArtifactRevisionId', working.last_preview_artifact_revision_id,
    'lastPreviewArtifactDigest', working.last_preview_artifact_digest
  );
END;
$$;

ALTER FUNCTION builder.read_preview_subject(p_account_id uuid, p_project_id uuid) OWNER TO builder_owner;

CREATE FUNCTION builder.recover_builder_runs() RETURNS SETOF uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  UPDATE builder.builder_run SET state = 'INTERRUPTED', failure_code = 'HUB_RESTART', finished_at = clock_timestamp()
  WHERE state IN ('QUEUED', 'RUNNING');
  RETURN QUERY SELECT builder_run_id FROM builder.builder_run WHERE state = 'QUEUED' ORDER BY created_at;
END;
$$;

ALTER FUNCTION builder.recover_builder_runs() OWNER TO builder_owner;

CREATE FUNCTION builder.request_builder_run_cancellation(p_account_id uuid, p_project_id uuid, p_builder_run_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE run_row builder.builder_run%ROWTYPE;
BEGIN
  PERFORM iam.admit_project(p_account_id, p_project_id, 'project.build');
  SELECT * INTO run_row FROM builder.builder_run
  WHERE builder_run_id = p_builder_run_id AND project_id = p_project_id AND account_id = p_account_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'BUILDER_RUN_NOT_FOUND'; END IF;
  IF run_row.state = 'QUEUED' THEN
    UPDATE builder.builder_run SET state = 'INTERRUPTED', cancellation_requested_at = COALESCE(cancellation_requested_at, clock_timestamp()),
      cancellation_reason = COALESCE(cancellation_reason, 'USER_CANCELLED'), finished_at = COALESCE(finished_at, clock_timestamp())
    WHERE builder_run_id = p_builder_run_id AND state = 'QUEUED';
  ELSIF run_row.state = 'RUNNING' THEN
    UPDATE builder.builder_run SET cancellation_requested_at = COALESCE(cancellation_requested_at, clock_timestamp()),
      cancellation_reason = COALESCE(cancellation_reason, 'USER_CANCELLED')
    WHERE builder_run_id = p_builder_run_id AND state = 'RUNNING';
  END IF;
  SELECT * INTO run_row FROM builder.builder_run WHERE builder_run_id = p_builder_run_id;
  RETURN jsonb_build_object(
    'builderRunId', run_row.builder_run_id, 'projectId', run_row.project_id,
    'state', run_row.state, 'phase', run_row.phase, 'mode', run_row.mode, 'baseSourceRevision', run_row.base_source_revision,
    'resultSourceRevision', run_row.result_source_revision, 'resultKind', run_row.result_kind,
    'failureCode', run_row.failure_code, 'modelAdmissionId', run_row.model_admission_id,
    'modelProviderId', run_row.model_provider_id, 'modelId', run_row.model_id,
    'cancellationRequested', run_row.cancellation_requested_at IS NOT NULL
  );
END;
$$;

ALTER FUNCTION builder.request_builder_run_cancellation(p_account_id uuid, p_project_id uuid, p_builder_run_id uuid) OWNER TO builder_owner;

CREATE FUNCTION builder.set_builder_run_phase(p_builder_run_id uuid, p_phase text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF p_phase IS NULL OR p_phase NOT IN ('PREPARING', 'AGENT', 'SOURCE_ADMISSION', 'COMPILING', 'FINALIZING') THEN
    RETURN false;
  END IF;
  UPDATE builder.builder_run
  SET phase = p_phase
  WHERE builder_run_id = p_builder_run_id
    AND state = 'RUNNING'
    AND cancellation_requested_at IS NULL;
  RETURN FOUND;
END;
$$;

ALTER FUNCTION builder.set_builder_run_phase(p_builder_run_id uuid, p_phase text) OWNER TO builder_owner;

CREATE FUNCTION builder.settle_builder_run(p_builder_run_id uuid, p_result_source_revision text, p_result_kind text, p_failure_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE run_row builder.builder_run%ROWTYPE; working builder.project_working_state%ROWTYPE;
BEGIN
  IF p_result_source_revision IS NOT NULL OR p_result_kind IS DISTINCT FROM 'RESPONSE_ONLY'
    OR p_failure_code IS NOT NULL THEN RETURN false; END IF;
  SELECT * INTO run_row FROM builder.builder_run WHERE builder_run_id = p_builder_run_id FOR UPDATE;
  IF NOT FOUND OR run_row.state <> 'RUNNING' THEN RETURN false; END IF;
  SELECT * INTO working FROM builder.project_working_state WHERE project_id = run_row.project_id FOR UPDATE;
  IF NOT FOUND OR working.working_version <> run_row.base_working_version THEN RETURN false; END IF;
  UPDATE builder.builder_run SET state = 'SUCCEEDED', result_source_revision = NULL,
    result_kind = 'RESPONSE_ONLY', failure_code = NULL, finished_at = clock_timestamp()
  WHERE builder_run_id = p_builder_run_id AND state = 'RUNNING';
  RETURN FOUND;
END;
$$;

ALTER FUNCTION builder.settle_builder_run(p_builder_run_id uuid, p_result_source_revision text, p_result_kind text, p_failure_code text) OWNER TO builder_owner;

CREATE FUNCTION builder.settle_builder_run_build(p_builder_run_id uuid, p_source_revision text, p_artifact_revision_id uuid, p_artifact_digest text, p_failure_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE run_row builder.builder_run%ROWTYPE; working builder.project_working_state%ROWTYPE;
BEGIN
  IF p_source_revision IS NULL OR p_source_revision !~ '^[0-9a-f]{40}$'
    OR (p_artifact_revision_id IS NULL) <> (p_artifact_digest IS NULL)
    OR (p_artifact_digest IS NOT NULL AND p_artifact_digest !~ '^[0-9a-f]{64}$')
    OR (p_artifact_revision_id IS NULL AND (p_failure_code IS NULL OR p_failure_code !~ '^[A-Z0-9_]{1,120}$'))
    OR (p_artifact_revision_id IS NOT NULL AND p_failure_code IS NOT NULL) THEN RETURN false; END IF;
  SELECT * INTO run_row FROM builder.builder_run WHERE builder_run_id = p_builder_run_id FOR UPDATE;
  IF NOT FOUND OR run_row.state <> 'RUNNING' OR run_row.mode <> 'BUILD'
    OR run_row.result_source_revision IS DISTINCT FROM p_source_revision THEN RETURN false; END IF;
  SELECT * INTO working FROM builder.project_working_state WHERE project_id = run_row.project_id FOR UPDATE;
  IF NOT FOUND OR working.working_source_revision IS DISTINCT FROM p_source_revision THEN RETURN false; END IF;
  IF p_artifact_revision_id IS NOT NULL THEN
    IF NOT reg.matches_application_artifact(run_row.project_id, p_source_revision, p_artifact_revision_id, p_artifact_digest) THEN
      RETURN false;
    END IF;
    UPDATE builder.project_working_state SET current_state = 'PREVIEW_READY',
      last_preview_source_revision = p_source_revision,
      last_preview_artifact_revision_id = p_artifact_revision_id,
      last_preview_artifact_digest = p_artifact_digest, updated_at = clock_timestamp()
    WHERE project_id = run_row.project_id;
    UPDATE builder.builder_run SET state = 'SUCCEEDED', result_kind = 'SOURCE_CHANGED', failure_code = NULL,
      finished_at = clock_timestamp() WHERE builder_run_id = p_builder_run_id;
  ELSE
    UPDATE builder.project_working_state SET current_state = 'BUILD_FAILED', updated_at = clock_timestamp()
    WHERE project_id = run_row.project_id;
    UPDATE builder.builder_run SET state = 'FAILED', result_kind = 'SOURCE_CHANGED_BUILD_FAILED', failure_code = p_failure_code,
      finished_at = clock_timestamp() WHERE builder_run_id = p_builder_run_id;
  END IF;
  RETURN true;
END;
$_$;

ALTER FUNCTION builder.settle_builder_run_build(p_builder_run_id uuid, p_source_revision text, p_artifact_revision_id uuid, p_artifact_digest text, p_failure_code text) OWNER TO builder_owner;

CREATE FUNCTION iam.account_is_active(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM iam.account AS stored_account
    WHERE stored_account.account_id = p_account_id AND stored_account.active
  );
$$;

ALTER FUNCTION iam.account_is_active(p_account_id uuid) OWNER TO iam_owner;

CREATE FUNCTION iam.admit_project(p_account_id uuid, p_project_id uuid, p_action iam.action) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  owning_workspace_id uuid;
BEGIN
  PERFORM 1
  FROM iam.account AS locked_account
  WHERE locked_account.account_id = p_account_id
  FOR SHARE;

  SELECT stored_project.workspace_id INTO owning_workspace_id
  FROM project.project AS stored_project
  WHERE stored_project.project_id = p_project_id;
  IF owning_workspace_id IS NULL THEN
    RAISE EXCEPTION 'NOT_ADMITTED' USING ERRCODE = '42501';
  END IF;
  PERFORM iam.admit_workspace(p_account_id, owning_workspace_id, p_action);
  RETURN owning_workspace_id;
END;
$$;

ALTER FUNCTION iam.admit_project(p_account_id uuid, p_project_id uuid, p_action iam.action) OWNER TO iam_owner;

CREATE FUNCTION iam.admit_workspace(p_account_id uuid, p_workspace_id uuid, p_action iam.action) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  PERFORM 1
  FROM iam.account AS admitted_account
  JOIN iam.workspace_membership AS membership
    ON membership.account_id = admitted_account.account_id
  WHERE admitted_account.account_id = p_account_id
    AND admitted_account.active
    AND membership.workspace_id = p_workspace_id
    AND iam.role_allows(membership.role, p_action)
  FOR SHARE OF admitted_account, membership;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_ADMITTED' USING ERRCODE = '42501';
  END IF;
END;
$$;

ALTER FUNCTION iam.admit_workspace(p_account_id uuid, p_workspace_id uuid, p_action iam.action) OWNER TO iam_owner;

CREATE FUNCTION iam.cancel_workspace_invitation(p_actor uuid, p_invitation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  invited_workspace_id uuid;
BEGIN
  SELECT invitation.workspace_id INTO invited_workspace_id
  FROM iam.workspace_invitation AS invitation
  WHERE invitation.invitation_id = p_invitation_id;
  IF invited_workspace_id IS NULL THEN
    RETURN;
  END IF;
  PERFORM iam.admit_workspace(p_actor, invited_workspace_id, 'members.manage');
  DELETE FROM iam.workspace_invitation AS invitation
  WHERE invitation.invitation_id = p_invitation_id;
END;
$$;

ALTER FUNCTION iam.cancel_workspace_invitation(p_actor uuid, p_invitation_id uuid) OWNER TO iam_owner;

CREATE FUNCTION iam.claim_invitations(p_account_id uuid, p_verified_email text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  claimed_count integer;
BEGIN
  IF p_verified_email IS NULL THEN
    RETURN 0;
  END IF;
  WITH claimed AS (
    DELETE FROM iam.workspace_invitation AS invitation
    WHERE invitation.email = lower(btrim(p_verified_email))
      AND invitation.expires_at > clock_timestamp()
    RETURNING invitation.workspace_id, invitation.role
  ), admitted AS (
    INSERT INTO iam.workspace_membership (account_id, workspace_id, role)
    SELECT p_account_id, claimed.workspace_id, claimed.role FROM claimed
    ON CONFLICT (account_id, workspace_id) DO NOTHING
    RETURNING iam.workspace_membership.workspace_id
  )
  SELECT count(*) FROM claimed INTO claimed_count;
  RETURN claimed_count;
END;
$$;

ALTER FUNCTION iam.claim_invitations(p_account_id uuid, p_verified_email text) OWNER TO iam_owner;

CREATE FUNCTION iam.email_has_open_invitation(p_verified_email text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM iam.workspace_invitation AS invitation
    WHERE p_verified_email IS NOT NULL
      AND invitation.email = lower(btrim(p_verified_email))
      AND invitation.expires_at > clock_timestamp());
$$;

ALTER FUNCTION iam.email_has_open_invitation(p_verified_email text) OWNER TO iam_owner;

CREATE FUNCTION iam.establish_workspace_creator_access(p_account_id uuid, p_workspace_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  INSERT INTO iam.workspace_membership (account_id, workspace_id, role)
  VALUES (p_account_id, p_workspace_id, 'owner');
$$;

ALTER FUNCTION iam.establish_workspace_creator_access(p_account_id uuid, p_workspace_id uuid) OWNER TO iam_owner;

CREATE FUNCTION iam.invite_workspace_member(p_actor uuid, p_workspace_id uuid, p_invitation_id uuid, p_email text, p_role iam.workspace_role, p_expires_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  settled_invitation_id uuid;
BEGIN
  PERFORM iam.admit_workspace(p_actor, p_workspace_id, 'members.manage');
  INSERT INTO iam.workspace_invitation (invitation_id, workspace_id, email, role, invited_by, expires_at)
  VALUES (p_invitation_id, p_workspace_id, lower(btrim(p_email)), p_role, p_actor, p_expires_at)
  ON CONFLICT (workspace_id, email) DO UPDATE
    SET role = EXCLUDED.role, invited_by = EXCLUDED.invited_by, expires_at = EXCLUDED.expires_at
  RETURNING iam.workspace_invitation.invitation_id INTO settled_invitation_id;
  RETURN settled_invitation_id;
END;
$$;

ALTER FUNCTION iam.invite_workspace_member(p_actor uuid, p_workspace_id uuid, p_invitation_id uuid, p_email text, p_role iam.workspace_role, p_expires_at timestamp with time zone) OWNER TO iam_owner;

CREATE FUNCTION iam.list_workspace_roster(p_actor uuid, p_workspace_id uuid) RETURNS TABLE(kind text, account_id uuid, invitation_id uuid, display_name text, email text, role iam.workspace_role, since timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT 'member'::text, member_account.account_id, NULL::uuid, member_account.display_name,
         member_account.email, membership.role, membership.created_at, NULL::timestamptz
  FROM iam.workspace_membership AS membership
  JOIN iam.account AS member_account ON member_account.account_id = membership.account_id
  WHERE membership.workspace_id = p_workspace_id
    AND p_workspace_id IN (SELECT visible.workspace_id FROM iam.visible_workspaces(p_actor) AS visible)
  UNION ALL
  SELECT 'invitation'::text, NULL::uuid, invitation.invitation_id, NULL::text,
         invitation.email, invitation.role, invitation.created_at, invitation.expires_at
  FROM iam.workspace_invitation AS invitation
  WHERE invitation.workspace_id = p_workspace_id
    AND p_workspace_id IN (SELECT visible.workspace_id FROM iam.visible_workspaces(p_actor) AS visible);
$$;

ALTER FUNCTION iam.list_workspace_roster(p_actor uuid, p_workspace_id uuid) OWNER TO iam_owner;

CREATE FUNCTION iam.remove_workspace_member(p_actor uuid, p_workspace_id uuid, p_member uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  PERFORM 1
  FROM iam.workspace_membership AS owner_membership
  WHERE owner_membership.workspace_id = p_workspace_id AND owner_membership.role = 'owner'
  ORDER BY owner_membership.account_id
  FOR UPDATE;

  IF p_actor = p_member THEN
    PERFORM iam.admit_workspace(p_actor, p_workspace_id, 'workspace.read');
  ELSE
    PERFORM iam.admit_workspace(p_actor, p_workspace_id, 'members.manage');
  END IF;

  IF EXISTS (
      SELECT 1 FROM iam.workspace_membership AS target_membership
      WHERE target_membership.workspace_id = p_workspace_id
        AND target_membership.account_id = p_member
        AND target_membership.role = 'owner')
    AND NOT EXISTS (
      SELECT 1 FROM iam.workspace_membership AS other_owner
      JOIN iam.account AS other_account
        ON other_account.account_id = other_owner.account_id AND other_account.active
      WHERE other_owner.workspace_id = p_workspace_id
        AND other_owner.role = 'owner'
        AND other_owner.account_id <> p_member)
  THEN
    RAISE EXCEPTION 'LAST_OWNER' USING ERRCODE = '42501';
  END IF;

  DELETE FROM iam.workspace_membership AS membership
  WHERE membership.workspace_id = p_workspace_id AND membership.account_id = p_member;
END;
$$;

ALTER FUNCTION iam.remove_workspace_member(p_actor uuid, p_workspace_id uuid, p_member uuid) OWNER TO iam_owner;

CREATE FUNCTION iam.role_allows(p_role iam.workspace_role, p_action iam.action) RETURNS boolean
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT CASE p_role
    WHEN 'owner' THEN true
    WHEN 'member' THEN p_action <> 'members.manage'
  END;
$$;

ALTER FUNCTION iam.role_allows(p_role iam.workspace_role, p_action iam.action) OWNER TO iam_owner;

CREATE FUNCTION iam.set_workspace_member_role(p_actor uuid, p_workspace_id uuid, p_member uuid, p_role iam.workspace_role) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  PERFORM 1
  FROM iam.workspace_membership AS owner_membership
  WHERE owner_membership.workspace_id = p_workspace_id AND owner_membership.role = 'owner'
  ORDER BY owner_membership.account_id
  FOR UPDATE;

  PERFORM iam.admit_workspace(p_actor, p_workspace_id, 'members.manage');

  IF p_role <> 'owner'
    AND EXISTS (
      SELECT 1 FROM iam.workspace_membership AS target_membership
      WHERE target_membership.workspace_id = p_workspace_id
        AND target_membership.account_id = p_member
        AND target_membership.role = 'owner')
    AND NOT EXISTS (
      SELECT 1 FROM iam.workspace_membership AS other_owner
      JOIN iam.account AS other_account
        ON other_account.account_id = other_owner.account_id AND other_account.active
      WHERE other_owner.workspace_id = p_workspace_id
        AND other_owner.role = 'owner'
        AND other_owner.account_id <> p_member)
  THEN
    RAISE EXCEPTION 'LAST_OWNER' USING ERRCODE = '42501';
  END IF;

  UPDATE iam.workspace_membership AS membership
  SET role = p_role
  WHERE membership.workspace_id = p_workspace_id AND membership.account_id = p_member;
END;
$$;

ALTER FUNCTION iam.set_workspace_member_role(p_actor uuid, p_workspace_id uuid, p_member uuid, p_role iam.workspace_role) OWNER TO iam_owner;

CREATE FUNCTION iam.visible_projects(p_account_id uuid) RETURNS TABLE(project_id uuid, workspace_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT stored_project.project_id, stored_project.workspace_id
  FROM project.project AS stored_project
  JOIN iam.visible_workspaces(p_account_id) AS visible
    ON visible.workspace_id = stored_project.workspace_id;
$$;

ALTER FUNCTION iam.visible_projects(p_account_id uuid) OWNER TO iam_owner;

CREATE FUNCTION iam.visible_workspaces(p_account_id uuid) RETURNS TABLE(workspace_id uuid, role iam.workspace_role)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT membership.workspace_id, membership.role
  FROM iam.workspace_membership AS membership
  JOIN iam.account AS admitted_account
    ON admitted_account.account_id = membership.account_id AND admitted_account.active
  WHERE membership.account_id = p_account_id;
$$;

ALTER FUNCTION iam.visible_workspaces(p_account_id uuid) OWNER TO iam_owner;

CREATE FUNCTION model_connection.admit_for_project(p_account_id uuid, p_project_id uuid, p_provider_id text) RETURNS TABLE(connection_id uuid, generation bigint, provider_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  admitted_workspace_id uuid;
BEGIN
  admitted_workspace_id := iam.admit_project(p_account_id, p_project_id, 'project.build');
  RETURN QUERY
  SELECT connection_row.connection_id, connection_row.current_generation, connection_row.provider_id
  FROM model_connection.preference AS preference
  JOIN model_connection.connection AS connection_row
    ON connection_row.connection_id = preference.connection_id
  WHERE preference.account_id = p_account_id
    AND connection_row.state = 'ACTIVE'
    AND (p_provider_id IS NULL OR connection_row.provider_id = p_provider_id)
    AND (
      connection_row.owner_account_id = p_account_id
      OR (
        EXISTS (
          SELECT 1 FROM model_connection.workspace_share AS share
          WHERE share.connection_id = connection_row.connection_id
            AND share.workspace_id = admitted_workspace_id)
        AND admitted_workspace_id IN (
          SELECT visible.workspace_id
          FROM iam.visible_workspaces(connection_row.owner_account_id) AS visible)
      )
    )
  ORDER BY preference.updated_at DESC
  LIMIT 1;
END;
$$;

ALTER FUNCTION model_connection.admit_for_project(p_account_id uuid, p_project_id uuid, p_provider_id text) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.advance_generation(p_connection_id uuid, p_expected_generation bigint, p_next_generation bigint) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  WITH advanced AS (
    UPDATE model_connection.connection
    SET current_generation = p_next_generation, updated_at = clock_timestamp()
    WHERE connection_id = p_connection_id AND state = 'ACTIVE'
      AND current_generation = p_expected_generation
      AND p_next_generation = p_expected_generation + 1
    RETURNING 1
  ) SELECT EXISTS (SELECT 1 FROM advanced);
$$;

ALTER FUNCTION model_connection.advance_generation(p_connection_id uuid, p_expected_generation bigint, p_next_generation bigint) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.complete_authorization(p_authorization_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  WITH completed AS (
    UPDATE model_connection.authorization
    SET status = 'COMPLETED'
    WHERE authorization_id = p_authorization_id AND status = 'EXCHANGING'
    RETURNING 1
  ) SELECT EXISTS (SELECT 1 FROM completed);
$$;

ALTER FUNCTION model_connection.complete_authorization(p_authorization_id uuid) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.consume_authorization(p_account_id uuid, p_state_digest bytea) RETURNS TABLE(authorization_id uuid, pkce_verifier text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE model_connection.authorization AS authorization_row
  SET status = 'EXCHANGING', consumed_at = clock_timestamp()
  WHERE authorization_row.account_id = p_account_id
    AND authorization_row.state_digest = p_state_digest
    AND authorization_row.status = 'PENDING'
    AND authorization_row.expires_at > clock_timestamp()
  RETURNING authorization_row.authorization_id, authorization_row.pkce_verifier;
END;
$$;

ALTER FUNCTION model_connection.consume_authorization(p_account_id uuid, p_state_digest bytea) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.fail_authorization(p_authorization_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  WITH failed AS (
    UPDATE model_connection.authorization
    SET status = 'FAILED'
    WHERE authorization_id = p_authorization_id AND status = 'EXCHANGING'
    RETURNING 1
  ) SELECT EXISTS (SELECT 1 FROM failed);
$$;

ALTER FUNCTION model_connection.fail_authorization(p_authorization_id uuid) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.list_connections(p_account_id uuid) RETURNS TABLE(connection_id uuid, label text, state text, current_generation bigint, owner_account_id uuid, workspace_id uuid, role text, revoked_at timestamp with time zone, provider_id text, credential_kind text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT visible.connection_id, visible.label, visible.state, visible.current_generation,
    visible.owner_account_id, visible.workspace_id, visible.role, visible.revoked_at,
    visible.provider_id, visible.credential_kind
  FROM (
    SELECT connection_row.connection_id, connection_row.label, connection_row.state,
      connection_row.current_generation, connection_row.owner_account_id,
      viewer.workspace_id, 'OWNER'::text AS role, connection_row.revoked_at,
      connection_row.provider_id, connection_row.credential_kind, connection_row.created_at
    FROM model_connection.connection AS connection_row
    CROSS JOIN iam.visible_workspaces(p_account_id) AS viewer
    WHERE connection_row.owner_account_id = p_account_id
    UNION ALL
    SELECT connection_row.connection_id, connection_row.label, connection_row.state,
      connection_row.current_generation, connection_row.owner_account_id,
      share.workspace_id, 'USER'::text AS role, connection_row.revoked_at,
      connection_row.provider_id, connection_row.credential_kind, connection_row.created_at
    FROM model_connection.connection AS connection_row
    JOIN model_connection.workspace_share AS share
      ON share.connection_id = connection_row.connection_id
    JOIN iam.visible_workspaces(p_account_id) AS viewer
      ON viewer.workspace_id = share.workspace_id
    WHERE connection_row.owner_account_id <> p_account_id
      AND share.workspace_id IN (
        SELECT owner_visible.workspace_id
        FROM iam.visible_workspaces(connection_row.owner_account_id) AS owner_visible)
  ) AS visible
  ORDER BY visible.created_at, visible.connection_id, visible.workspace_id;
$$;

ALTER FUNCTION model_connection.list_connections(p_account_id uuid) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.publish_connection(p_account_id uuid, p_connection_id uuid, p_provider_id text, p_credential_kind text, p_label text, p_generation bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
BEGIN
  IF p_generation <= 0 OR p_label !~ '[^[:space:]]' OR length(p_label) > 120
    OR p_provider_id IS NULL OR p_provider_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$'
    OR p_credential_kind IS NULL OR p_credential_kind NOT IN ('OAUTH_TOKEN_SET', 'API_KEY') THEN RETURN false; END IF;
  IF NOT iam.account_is_active(p_account_id) THEN RETURN false; END IF;
  INSERT INTO model_connection.connection(
    connection_id, owner_account_id, provider_id, credential_kind, label, state, current_generation)
  VALUES (p_connection_id, p_account_id, p_provider_id, p_credential_kind, btrim(p_label), 'ACTIVE', p_generation);
  RETURN true;
END;
$_$;

ALTER FUNCTION model_connection.publish_connection(p_account_id uuid, p_connection_id uuid, p_provider_id text, p_credential_kind text, p_label text, p_generation bigint) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.read_connection_credential(p_connection_id uuid) RETURNS TABLE(provider_id text, credential_kind text, current_generation bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT connection_row.provider_id, connection_row.credential_kind, connection_row.current_generation
  FROM model_connection.connection AS connection_row
  WHERE connection_row.connection_id = p_connection_id AND connection_row.state = 'ACTIVE';
$$;

ALTER FUNCTION model_connection.read_connection_credential(p_connection_id uuid) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.read_current_generation(p_connection_id uuid) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT current_generation FROM model_connection.connection
  WHERE connection_id = p_connection_id AND state = 'ACTIVE';
$$;

ALTER FUNCTION model_connection.read_current_generation(p_connection_id uuid) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.revoke_connection(p_account_id uuid, p_connection_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE selected model_connection.connection%ROWTYPE;
BEGIN
  SELECT * INTO selected FROM model_connection.connection
  WHERE connection_id = p_connection_id FOR UPDATE;
  IF NOT FOUND OR selected.owner_account_id <> p_account_id THEN RETURN false; END IF;
  IF selected.state = 'REVOKED' THEN RETURN true; END IF;
  UPDATE model_connection.connection
  SET state = 'REVOKED', revoked_at = clock_timestamp(), updated_at = clock_timestamp()
  WHERE connection_id = p_connection_id;
  DELETE FROM model_connection.preference WHERE connection_id = p_connection_id;
  DELETE FROM model_connection.workspace_share WHERE connection_id = p_connection_id;
  RETURN true;
END;
$$;

ALTER FUNCTION model_connection.revoke_connection(p_account_id uuid, p_connection_id uuid) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.select_connection(p_account_id uuid, p_connection_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE selected model_connection.connection%ROWTYPE;
BEGIN
  SELECT connection_row.* INTO selected
  FROM model_connection.connection AS connection_row
  WHERE connection_row.connection_id = p_connection_id
    AND connection_row.state = 'ACTIVE'
    AND (
      connection_row.owner_account_id = p_account_id
      OR EXISTS (
        SELECT 1
        FROM model_connection.workspace_share AS share
        JOIN iam.visible_workspaces(p_account_id) AS viewer
          ON viewer.workspace_id = share.workspace_id
        WHERE share.connection_id = connection_row.connection_id
          AND share.workspace_id IN (
            SELECT owner_visible.workspace_id
            FROM iam.visible_workspaces(connection_row.owner_account_id) AS owner_visible))
    )
  FOR UPDATE OF connection_row;
  IF NOT FOUND THEN RETURN false; END IF;
  INSERT INTO model_connection.preference(account_id, connection_id, provider_id)
  VALUES (p_account_id, p_connection_id, selected.provider_id)
  ON CONFLICT (account_id, provider_id)
  DO UPDATE SET connection_id = EXCLUDED.connection_id, updated_at = clock_timestamp();
  RETURN true;
END;
$$;

ALTER FUNCTION model_connection.select_connection(p_account_id uuid, p_connection_id uuid) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.share_connection(p_owner_account_id uuid, p_connection_id uuid, p_workspace_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE selected model_connection.connection%ROWTYPE;
BEGIN
  PERFORM iam.admit_workspace(p_owner_account_id, p_workspace_id, 'connection.share');
  SELECT * INTO selected FROM model_connection.connection
  WHERE connection_id = p_connection_id FOR UPDATE;
  IF NOT FOUND OR selected.owner_account_id <> p_owner_account_id OR selected.state <> 'ACTIVE' THEN
    RETURN false;
  END IF;
  INSERT INTO model_connection.workspace_share (connection_id, workspace_id)
  VALUES (p_connection_id, p_workspace_id)
  ON CONFLICT (connection_id, workspace_id) DO NOTHING;
  RETURN true;
END;
$$;

ALTER FUNCTION model_connection.share_connection(p_owner_account_id uuid, p_connection_id uuid, p_workspace_id uuid) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.start_authorization(p_authorization_id uuid, p_account_id uuid, p_state_digest bytea, p_pkce_verifier text, p_expires_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
BEGIN
  IF p_state_digest IS NULL OR octet_length(p_state_digest) <> 32
    OR p_pkce_verifier !~ '^[A-Za-z0-9_-]{43,128}$'
    OR p_expires_at <= clock_timestamp() THEN RETURN false; END IF;
  INSERT INTO model_connection.authorization(
    authorization_id, account_id, state_digest, pkce_verifier, expires_at, status
  ) VALUES (p_authorization_id, p_account_id, p_state_digest, p_pkce_verifier, p_expires_at, 'PENDING');
  RETURN true;
END;
$_$;

ALTER FUNCTION model_connection.start_authorization(p_authorization_id uuid, p_account_id uuid, p_state_digest bytea, p_pkce_verifier text, p_expires_at timestamp with time zone) OWNER TO model_connection_owner;

CREATE FUNCTION model_connection.unshare_connection(p_actor_account_id uuid, p_connection_id uuid, p_workspace_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE selected model_connection.connection%ROWTYPE;
BEGIN
  SELECT * INTO selected FROM model_connection.connection
  WHERE connection_id = p_connection_id FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  IF selected.owner_account_id = p_actor_account_id THEN
    PERFORM iam.admit_workspace(p_actor_account_id, p_workspace_id, 'workspace.read');
  ELSE
    PERFORM iam.admit_workspace(p_actor_account_id, p_workspace_id, 'members.manage');
  END IF;
  DELETE FROM model_connection.workspace_share AS share
  WHERE share.connection_id = p_connection_id AND share.workspace_id = p_workspace_id;
  RETURN true;
END;
$$;

ALTER FUNCTION model_connection.unshare_connection(p_actor_account_id uuid, p_connection_id uuid, p_workspace_id uuid) OWNER TO model_connection_owner;

CREATE FUNCTION project.claim_abandoned_create_project_attempt(p_expired_before timestamp with time zone, p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, key_digest text, request_digest text, project_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF p_expired_before IS NULL OR p_expired_before > statement_timestamp() THEN
    RAISE EXCEPTION 'PRJ03_ABANDONED_SCAN_CUTOFF_REFUSED' USING ERRCODE = 'P0001';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 16 THEN
    RAISE EXCEPTION 'PRJ03_ABANDONED_SCAN_LIMIT_REFUSED' USING ERRCODE = 'P0001';
  END IF;

  RETURN QUERY
  WITH candidates AS MATERIALIZED (
    SELECT operation_receipt.operation_id,
      operation_receipt.account_id,
      operation_receipt.workspace_id,
      operation_receipt.key_digest,
      operation_receipt.request_digest,
      operation_receipt.reserved_project_id,
      operation_receipt.created_at
    FROM project.operation_idempotency AS operation_receipt
    WHERE operation_receipt.operation_id = 'PRJ-03'
      AND operation_receipt.outcome = 'RESERVED'
      AND operation_receipt.response_status IS NULL
      AND operation_receipt.response_digest IS NULL
      AND operation_receipt.response_body IS NULL
      AND operation_receipt.completed_at IS NULL
      AND operation_receipt.created_at <= p_expired_before
      AND NOT EXISTS (
        SELECT 1
        FROM project.project AS stored_project
        WHERE stored_project.project_id = operation_receipt.reserved_project_id
      )
    ORDER BY operation_receipt.created_at,
      operation_receipt.account_id,
      operation_receipt.workspace_id,
      operation_receipt.key_digest
    FOR UPDATE OF operation_receipt SKIP LOCKED
    LIMIT p_limit
  ), deleted AS (
    DELETE FROM project.operation_idempotency AS operation_receipt
    USING candidates
    WHERE operation_receipt.operation_id = candidates.operation_id
      AND operation_receipt.account_id = candidates.account_id
      AND operation_receipt.workspace_id = candidates.workspace_id
      AND operation_receipt.key_digest = candidates.key_digest
    RETURNING operation_receipt.account_id,
      operation_receipt.workspace_id,
      operation_receipt.key_digest,
      operation_receipt.request_digest,
      operation_receipt.reserved_project_id
  )
  SELECT deleted.account_id,
    deleted.workspace_id,
    deleted.key_digest,
    deleted.request_digest,
    deleted.reserved_project_id
  FROM deleted
  JOIN candidates
    ON candidates.operation_id = 'PRJ-03'
    AND candidates.account_id = deleted.account_id
    AND candidates.workspace_id = deleted.workspace_id
    AND candidates.key_digest = deleted.key_digest
  ORDER BY candidates.created_at,
    deleted.account_id,
    deleted.workspace_id,
    deleted.key_digest;
END;
$$;

ALTER FUNCTION project.claim_abandoned_create_project_attempt(p_expired_before timestamp with time zone, p_limit integer) OWNER TO project_owner;

CREATE FUNCTION project.claim_abandoned_create_project_attempt(p_account_id uuid, p_workspace_id uuid, p_key_digest text, p_request_digest text, p_project_id uuid, p_expired_before timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  receipt project.operation_idempotency%ROWTYPE;
BEGIN
  SELECT * INTO receipt
  FROM project.operation_idempotency AS operation_receipt
  WHERE operation_receipt.operation_id = 'PRJ-03'
    AND operation_receipt.account_id = p_account_id
    AND operation_receipt.workspace_id = p_workspace_id
    AND operation_receipt.key_digest = p_key_digest
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRJ03_ABANDONED_RECEIPT_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF receipt.request_digest <> p_request_digest OR receipt.reserved_project_id <> p_project_id THEN
    RAISE EXCEPTION 'PRJ03_ABANDONED_RECEIPT_IDENTITY_MISMATCH' USING ERRCODE = 'P0001';
  END IF;
  IF receipt.outcome <> 'RESERVED'
    OR receipt.response_status IS NOT NULL
    OR receipt.response_digest IS NOT NULL
    OR receipt.response_body IS NOT NULL
    OR receipt.completed_at IS NOT NULL THEN
    RAISE EXCEPTION 'PRJ03_ABANDONED_RECEIPT_TERMINAL' USING ERRCODE = 'P0001';
  END IF;
  IF p_expired_before IS NULL
    OR p_expired_before > statement_timestamp()
    OR receipt.created_at > p_expired_before THEN
    RAISE EXCEPTION 'PRJ03_ABANDONED_RECEIPT_NOT_EXPIRED' USING ERRCODE = 'P0001';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM project.project AS stored_project
    WHERE stored_project.project_id = receipt.reserved_project_id
  ) THEN
    RAISE EXCEPTION 'PRJ03_ABANDONED_PROJECT_EXISTS' USING ERRCODE = 'P0001';
  END IF;

  DELETE FROM project.operation_idempotency AS operation_receipt
  WHERE operation_receipt.operation_id = receipt.operation_id
    AND operation_receipt.account_id = receipt.account_id
    AND operation_receipt.workspace_id = receipt.workspace_id
    AND operation_receipt.key_digest = receipt.key_digest
    AND operation_receipt.request_digest = receipt.request_digest
    AND operation_receipt.reserved_project_id = receipt.reserved_project_id
    AND operation_receipt.outcome = 'RESERVED';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRJ03_ABANDONED_RECEIPT_CHANGED' USING ERRCODE = 'P0001';
  END IF;

  RETURN receipt.reserved_project_id;
END;
$$;

ALTER FUNCTION project.claim_abandoned_create_project_attempt(p_account_id uuid, p_workspace_id uuid, p_key_digest text, p_request_digest text, p_project_id uuid, p_expired_before timestamp with time zone) OWNER TO project_owner;

CREATE FUNCTION project.complete_create_project_receipt(p_account_id uuid, p_workspace_id uuid, p_key_digest text, p_request_digest text, p_project_id uuid, p_response_status integer, p_response_digest text, p_response_body jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  PERFORM iam.admit_workspace(p_account_id, p_workspace_id, 'project.create');

  PERFORM 1
  FROM project.project AS stored_project
  WHERE stored_project.project_id = p_project_id
    AND stored_project.workspace_id = p_workspace_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRJ03_SETTLEMENT_INCOMPLETE' USING ERRCODE = 'P0001';
  END IF;

  UPDATE project.operation_idempotency
  SET outcome = 'SUCCEEDED', response_status = p_response_status,
      response_digest = p_response_digest, response_body = p_response_body,
      completed_at = clock_timestamp()
  WHERE operation_id = 'PRJ-03'
    AND account_id = p_account_id
    AND workspace_id = p_workspace_id
    AND key_digest = p_key_digest
    AND request_digest = p_request_digest
    AND reserved_project_id = p_project_id
    AND outcome = 'RESERVED';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRJ03_RECEIPT_NOT_RESERVED' USING ERRCODE = 'P0001';
  END IF;
END;
$$;

ALTER FUNCTION project.complete_create_project_receipt(p_account_id uuid, p_workspace_id uuid, p_key_digest text, p_request_digest text, p_project_id uuid, p_response_status integer, p_response_digest text, p_response_body jsonb) OWNER TO project_owner;

CREATE FUNCTION project.create_project_with_source(p_account_id uuid, p_workspace_id uuid, p_key_digest text, p_request_digest text, p_project_id uuid, p_name text, p_source_mode text, p_source_revision text, p_project_revision text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  PERFORM 1
  FROM project.operation_idempotency AS operation_receipt
  WHERE operation_receipt.operation_id = 'PRJ-03'
    AND operation_receipt.account_id = p_account_id
    AND operation_receipt.workspace_id = p_workspace_id
    AND operation_receipt.key_digest = p_key_digest
    AND operation_receipt.request_digest = p_request_digest
    AND operation_receipt.reserved_project_id = p_project_id
    AND operation_receipt.outcome = 'RESERVED'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRJ03_RECEIPT_NOT_RESERVED' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO project.project (
    project_id, workspace_id, name, source_mode, source_revision, project_revision
  ) VALUES (
    p_project_id, p_workspace_id, p_name, p_source_mode, p_source_revision, p_project_revision
  );

  INSERT INTO builder.project_working_state(project_id, working_source_revision)
  VALUES (p_project_id, p_source_revision);
END;
$$;

ALTER FUNCTION project.create_project_with_source(p_account_id uuid, p_workspace_id uuid, p_key_digest text, p_request_digest text, p_project_id uuid, p_name text, p_source_mode text, p_source_revision text, p_project_revision text) OWNER TO project_owner;

CREATE FUNCTION project.get_project(p_account_id uuid, p_project_id uuid) RETURNS TABLE(project_id uuid, workspace_id uuid, name text, project_revision text, archived boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT stored_project.project_id, stored_project.workspace_id,
    stored_project.name, stored_project.project_revision, stored_project.archived
  FROM project.project AS stored_project
  JOIN iam.visible_projects(p_account_id) AS visible
    ON visible.project_id = stored_project.project_id
  WHERE stored_project.project_id = p_project_id;
$$;

ALTER FUNCTION project.get_project(p_account_id uuid, p_project_id uuid) OWNER TO project_owner;

CREATE FUNCTION project.list_project_summaries(p_account_id uuid, p_workspace_id uuid) RETURNS TABLE(project_id uuid, workspace_id uuid, name text, archived boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT stored_project.project_id, stored_project.workspace_id,
    stored_project.name, stored_project.archived
  FROM project.project AS stored_project
