ALTER FUNCTION project.list_project_summaries(p_account_id uuid, p_workspace_id uuid) OWNER TO project_owner;

CREATE FUNCTION project.lock_create_project_receipt(p_account_id uuid, p_workspace_id uuid, p_key_digest text, p_request_digest text, p_project_id uuid) RETURNS TABLE(outcome text, project_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  receipt project.operation_idempotency%ROWTYPE;
BEGIN
  PERFORM iam.admit_workspace(p_account_id, p_workspace_id, 'project.create');

  SELECT * INTO STRICT receipt
  FROM project.operation_idempotency AS operation_receipt
  WHERE operation_receipt.operation_id = 'PRJ-03'
    AND operation_receipt.account_id = p_account_id
    AND operation_receipt.workspace_id = p_workspace_id
    AND operation_receipt.key_digest = p_key_digest
  FOR UPDATE;

  IF receipt.request_digest <> p_request_digest OR receipt.reserved_project_id <> p_project_id THEN
    RAISE EXCEPTION 'PRJ03_RECEIPT_IDENTITY_MISMATCH' USING ERRCODE = 'P0001';
  END IF;

  RETURN QUERY SELECT receipt.outcome, receipt.reserved_project_id;
END;
$$;

ALTER FUNCTION project.lock_create_project_receipt(p_account_id uuid, p_workspace_id uuid, p_key_digest text, p_request_digest text, p_project_id uuid) OWNER TO project_owner;

CREATE FUNCTION project.reserve_or_replay_create_project(p_account_id uuid, p_workspace_id uuid, p_key_digest text, p_request_digest text, p_candidate_project_id uuid) RETURNS TABLE(state text, project_id uuid, response_status integer, response_body jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  receipt project.operation_idempotency%ROWTYPE;
  inserted_count integer;
BEGIN
  PERFORM iam.admit_workspace(p_account_id, p_workspace_id, 'project.create');

  BEGIN
    INSERT INTO project.operation_idempotency (
      operation_id, account_id, workspace_id, key_digest, request_digest, reserved_project_id, outcome
    ) VALUES (
      'PRJ-03', p_account_id, p_workspace_id, p_key_digest, p_request_digest, p_candidate_project_id, 'RESERVED'
    ) ON CONFLICT (operation_id, account_id, workspace_id, key_digest) DO NOTHING;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'PRJ03_PROJECT_ID_ALREADY_RESERVED' USING ERRCODE = 'P0001';
  END;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;

  IF inserted_count = 1 AND EXISTS (
    SELECT 1 FROM project.project AS stored_project
    WHERE stored_project.project_id = p_candidate_project_id
  ) THEN
    RAISE EXCEPTION 'PRJ03_PROJECT_ID_ALREADY_EXISTS' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO STRICT receipt
  FROM project.operation_idempotency AS operation_receipt
  WHERE operation_receipt.operation_id = 'PRJ-03'
    AND operation_receipt.account_id = p_account_id
    AND operation_receipt.workspace_id = p_workspace_id
    AND operation_receipt.key_digest = p_key_digest
  FOR UPDATE;

  IF receipt.request_digest <> p_request_digest THEN
    RETURN QUERY SELECT 'CONFLICT'::text, receipt.reserved_project_id, NULL::integer, NULL::jsonb;
  ELSIF receipt.outcome = 'SUCCEEDED' THEN
    RETURN QUERY SELECT 'REPLAY'::text, receipt.reserved_project_id, receipt.response_status, receipt.response_body;
  ELSE
    RETURN QUERY SELECT 'RESERVED'::text, receipt.reserved_project_id, NULL::integer, NULL::jsonb;
  END IF;
END;
$$;

ALTER FUNCTION project.reserve_or_replay_create_project(p_account_id uuid, p_workspace_id uuid, p_key_digest text, p_request_digest text, p_candidate_project_id uuid) OWNER TO project_owner;

CREATE FUNCTION reg.get_application_by_source(p_account_id uuid, p_project_id uuid, p_source_revision text) RETURNS TABLE(artifact_revision_id uuid, artifact_digest text, project_id uuid, source_revision text, profile text, template_ref text, recipe_sha256 text, entry_path text, files jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE
  artifact_row reg.artifact%ROWTYPE;
  revision_row reg.artifact_revision%ROWTYPE;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM iam.visible_projects(p_account_id) AS visible
    WHERE visible.project_id = p_project_id)
    OR p_source_revision IS NULL OR p_source_revision !~ '^[0-9a-f]{40}$' THEN RETURN; END IF;
  SELECT artifact.* INTO STRICT artifact_row FROM reg.artifact AS artifact
  WHERE artifact.project_id = p_project_id AND artifact.kind = 'application';
  SELECT revision.* INTO STRICT revision_row FROM reg.artifact_revision AS revision
  WHERE revision.artifact_id = artifact_row.artifact_id
    AND revision.source_revision = p_source_revision
    AND revision.availability = 'AVAILABLE';
  RETURN QUERY SELECT revision_row.artifact_revision_id, revision_row.digest, artifact_row.project_id,
    revision_row.source_revision, revision_row.payload->>'profile', revision_row.payload->>'templateRef',
    revision_row.payload->>'recipeSha256', revision_row.payload->>'entryPath',
    (SELECT jsonb_agg(jsonb_build_object(
      'path', value->>'path', 'mediaType', value->>'mediaType',
      'byteLength', (value->>'byteLength')::integer, 'sha256', value->>'sha256'
    ) ORDER BY value->>'path' COLLATE "C") FROM jsonb_array_elements(revision_row.payload->'files') AS values(value));
EXCEPTION WHEN no_data_found THEN
  RETURN;
END;
$_$;

ALTER FUNCTION reg.get_application_by_source(p_account_id uuid, p_project_id uuid, p_source_revision text) OWNER TO registry_owner;

CREATE FUNCTION reg.matches_application_artifact(p_project_id uuid, p_source_revision text, p_artifact_revision_id uuid, p_artifact_digest text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM reg.artifact AS artifact
    JOIN reg.artifact_revision AS revision ON revision.artifact_id = artifact.artifact_id
    WHERE artifact.project_id = p_project_id
      AND artifact.kind = 'application'
      AND revision.source_revision = p_source_revision
      AND revision.artifact_revision_id = p_artifact_revision_id
      AND revision.digest = p_artifact_digest
      AND revision.availability = 'AVAILABLE'
  );
$$;

ALTER FUNCTION reg.matches_application_artifact(p_project_id uuid, p_source_revision text, p_artifact_revision_id uuid, p_artifact_digest text) OWNER TO registry_owner;

CREATE FUNCTION reg.read_application_file_by_source(p_account_id uuid, p_project_id uuid, p_source_revision text, p_artifact_revision_id uuid, p_path text) RETURNS TABLE(artifact_revision_id uuid, project_id uuid, source_revision text, path text, media_type text, bytes bytea, sha256 text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE
  artifact_row reg.artifact%ROWTYPE;
  revision_row reg.artifact_revision%ROWTYPE;
  file_row jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM iam.visible_projects(p_account_id) AS visible
    WHERE visible.project_id = p_project_id)
    OR p_source_revision IS NULL OR p_source_revision !~ '^[0-9a-f]{40}$' THEN RETURN; END IF;
  SELECT artifact.* INTO STRICT artifact_row FROM reg.artifact AS artifact
  WHERE artifact.project_id = p_project_id AND artifact.kind = 'application';
  SELECT revision.* INTO STRICT revision_row FROM reg.artifact_revision AS revision
  WHERE revision.artifact_id = artifact_row.artifact_id
    AND revision.artifact_revision_id = p_artifact_revision_id
    AND revision.source_revision = p_source_revision
    AND revision.availability = 'AVAILABLE';
  SELECT value INTO STRICT file_row FROM jsonb_array_elements(revision_row.payload->'files') AS values(value)
  WHERE value->>'path' = p_path;
  RETURN QUERY SELECT revision_row.artifact_revision_id, artifact_row.project_id,
    revision_row.source_revision, file_row->>'path', file_row->>'mediaType',
    decode(file_row->>'base64', 'base64'), file_row->>'sha256';
EXCEPTION WHEN no_data_found THEN
  RETURN;
END;
$_$;

ALTER FUNCTION reg.read_application_file_by_source(p_account_id uuid, p_project_id uuid, p_source_revision text, p_artifact_revision_id uuid, p_path text) OWNER TO registry_owner;

CREATE FUNCTION reg.retain_application_execution(p_account_id uuid, p_project_id uuid, p_execution_id uuid, p_source_revision text, p_payload jsonb) RETURNS TABLE(artifact_revision_id uuid, artifact_digest text, project_id uuid, source_revision text, profile text, template_ref text, recipe_sha256 text, entry_path text, files jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE
  artifact_row reg.artifact%ROWTYPE;
  revision_row reg.artifact_revision%ROWTYPE;
  item jsonb;
  computed_digest text;
  expected_media_type text;
  decoded_bytes bytea;
  previous_path text;
  total_bytes bigint := 0;
  item_count integer;
BEGIN
  IF p_account_id IS NULL OR p_project_id IS NULL OR p_execution_id IS NULL OR p_source_revision IS NULL
    OR p_source_revision !~ '^[0-9a-f]{40}$' THEN
    RAISE EXCEPTION 'APPLICATION_INPUT_REFUSED' USING ERRCODE = 'P0001';
  END IF;
  IF NOT COALESCE(builder.admit_verified_application_source(
    p_account_id, p_project_id, p_execution_id, p_source_revision
  ), false) THEN
    RAISE EXCEPTION 'APPLICATION_SUBJECT_REFUSED' USING ERRCODE = 'P0001';
  END IF;

  IF p_payload IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
    OR (SELECT count(*) FROM jsonb_object_keys(p_payload)) <> 8
    OR NOT (p_payload ? 'format') OR NOT (p_payload ? 'profile')
    OR NOT (p_payload ? 'projectId') OR NOT (p_payload ? 'sourceRevision')
    OR NOT (p_payload ? 'templateRef') OR NOT (p_payload ? 'recipeSha256')
    OR NOT (p_payload ? 'entryPath') OR NOT (p_payload ? 'files') THEN
    RAISE EXCEPTION 'APPLICATION_PAYLOAD_REFUSED' USING ERRCODE = 'P0001';
  END IF;
  IF jsonb_typeof(p_payload->'format') IS DISTINCT FROM 'string'
    OR p_payload->>'format' IS DISTINCT FROM 'application-payload-v1'
    OR jsonb_typeof(p_payload->'profile') IS DISTINCT FROM 'string'
    OR p_payload->>'profile' IS DISTINCT FROM 'REACT_VITE_V1'
    OR jsonb_typeof(p_payload->'projectId') IS DISTINCT FROM 'string'
    OR p_payload->>'projectId' IS DISTINCT FROM p_project_id::text
    OR jsonb_typeof(p_payload->'sourceRevision') IS DISTINCT FROM 'string'
    OR p_payload->>'sourceRevision' IS DISTINCT FROM p_source_revision
    OR jsonb_typeof(p_payload->'templateRef') IS DISTINCT FROM 'string'
    OR p_payload->>'templateRef' IS DISTINCT FROM 'xdli9puqp1nepk4ht6lw:8a1e3885-c6d7-4b06-aea6-860632f407e6'
    OR jsonb_typeof(p_payload->'recipeSha256') IS DISTINCT FROM 'string'
    OR p_payload->>'recipeSha256' IS DISTINCT FROM '32230b4ba0b72625474b7f722e2294a256f9ab2f7c1c9b1eb107f38770edbe97'
    OR jsonb_typeof(p_payload->'entryPath') IS DISTINCT FROM 'string'
    OR p_payload->>'entryPath' IS DISTINCT FROM 'index.html'
    OR jsonb_typeof(p_payload->'files') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'APPLICATION_PAYLOAD_PIN_REFUSED' USING ERRCODE = 'P0001';
  END IF;

  item_count := jsonb_array_length(p_payload->'files');
  IF item_count < 1 OR item_count > 256 THEN
    RAISE EXCEPTION 'APPLICATION_FILE_COUNT_REFUSED' USING ERRCODE = 'P0001';
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(p_payload->'files') WITH ORDINALITY AS elements(value, position)
  LOOP
    IF jsonb_typeof(item) IS DISTINCT FROM 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(item)) <> 5
      OR NOT (item ? 'path') OR NOT (item ? 'mediaType') OR NOT (item ? 'byteLength')
      OR NOT (item ? 'sha256') OR NOT (item ? 'base64')
      OR jsonb_typeof(item->'path') IS DISTINCT FROM 'string'
      OR jsonb_typeof(item->'mediaType') IS DISTINCT FROM 'string'
      OR jsonb_typeof(item->'byteLength') IS DISTINCT FROM 'number'
      OR jsonb_typeof(item->'sha256') IS DISTINCT FROM 'string'
      OR jsonb_typeof(item->'base64') IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION 'APPLICATION_FILE_SHAPE_REFUSED' USING ERRCODE = 'P0001';
    END IF;
    IF length(item->>'path') < 1 OR length(item->>'path') > 1024
      OR item->>'path' !~ '^[A-Za-z0-9][A-Za-z0-9._-]*(/[A-Za-z0-9][A-Za-z0-9._-]*)*$'
      OR (item->>'path') COLLATE "C" <= (COALESCE(previous_path, '')) COLLATE "C" THEN
      RAISE EXCEPTION 'APPLICATION_FILE_PATH_REFUSED' USING ERRCODE = 'P0001';
    END IF;
    previous_path := item->>'path';
    IF item->>'path' = 'index.html' AND item->>'mediaType' <> 'text/html; charset=utf-8' THEN
      RAISE EXCEPTION 'APPLICATION_ENTRYPOINT_REFUSED' USING ERRCODE = 'P0001';
    END IF;
    expected_media_type := CASE lower(regexp_replace(item->>'path', '^.*(\.[^./]*)$', '\1'))
      WHEN '.avif' THEN 'image/avif'
      WHEN '.cjs' THEN 'text/javascript; charset=utf-8'
      WHEN '.css' THEN 'text/css; charset=utf-8'
      WHEN '.gif' THEN 'image/gif'
      WHEN '.html' THEN 'text/html; charset=utf-8'
      WHEN '.ico' THEN 'image/x-icon'
      WHEN '.jpeg' THEN 'image/jpeg'
      WHEN '.jpg' THEN 'image/jpeg'
      WHEN '.js' THEN 'text/javascript; charset=utf-8'
      WHEN '.json' THEN 'application/json; charset=utf-8'
      WHEN '.mjs' THEN 'text/javascript; charset=utf-8'
      WHEN '.otf' THEN 'font/otf'
      WHEN '.png' THEN 'image/png'
      WHEN '.svg' THEN 'image/svg+xml'
      WHEN '.txt' THEN 'text/plain; charset=utf-8'
      WHEN '.wasm' THEN 'application/wasm'
      WHEN '.webp' THEN 'image/webp'
      WHEN '.woff' THEN 'font/woff'
      WHEN '.woff2' THEN 'font/woff2'
      ELSE NULL
    END;
    IF expected_media_type IS NULL OR item->>'mediaType' IS DISTINCT FROM expected_media_type THEN
      RAISE EXCEPTION 'APPLICATION_MEDIA_TYPE_REFUSED' USING ERRCODE = 'P0001';
    END IF;
    IF item->>'byteLength' !~ '^[0-9]+$' OR length(item->>'byteLength') > 8
      OR (item->>'byteLength')::bigint > 12582912 THEN
      RAISE EXCEPTION 'APPLICATION_FILE_SIZE_REFUSED' USING ERRCODE = 'P0001';
    END IF;
    IF item->>'sha256' !~ '^[a-f0-9]{64}$' THEN
      RAISE EXCEPTION 'APPLICATION_FILE_HASH_REFUSED' USING ERRCODE = 'P0001';
    END IF;
    IF length(item->>'base64') > 16777216
      OR length(item->>'base64') <> ((((item->>'byteLength')::bigint + 2) / 3) * 4)::integer THEN
      RAISE EXCEPTION 'APPLICATION_FILE_ENCODING_REFUSED' USING ERRCODE = 'P0001';
    END IF;
    decoded_bytes := decode(item->>'base64', 'base64');
    IF item->>'base64' <> regexp_replace(encode(decoded_bytes, 'base64'), E'[\r\n]', '', 'g')
      OR octet_length(decoded_bytes) <> (item->>'byteLength')::bigint
      OR encode(sha256(decoded_bytes), 'hex') IS DISTINCT FROM item->>'sha256' THEN
      RAISE EXCEPTION 'APPLICATION_FILE_ENCODING_REFUSED' USING ERRCODE = 'P0001';
    END IF;
    total_bytes := total_bytes + octet_length(decoded_bytes);
    IF total_bytes > 12582912 THEN
      RAISE EXCEPTION 'APPLICATION_TOTAL_SIZE_REFUSED' USING ERRCODE = 'P0001';
    END IF;
  END LOOP;
  IF previous_path IS DISTINCT FROM (SELECT value->>'path' FROM jsonb_array_elements(p_payload->'files') AS values(value)
    ORDER BY value->>'path' COLLATE "C" DESC LIMIT 1)
    OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'files') AS values(value) WHERE value->>'path' = 'index.html') THEN
    RAISE EXCEPTION 'APPLICATION_FILE_ORDER_REFUSED' USING ERRCODE = 'P0001';
  END IF;
  IF (SELECT count(DISTINCT value->>'path') FROM jsonb_array_elements(p_payload->'files') AS values(value)) <> item_count THEN
    RAISE EXCEPTION 'APPLICATION_FILE_DUPLICATE_REFUSED' USING ERRCODE = 'P0001';
  END IF;

  computed_digest := encode(sha256(convert_to(p_payload::text, 'UTF8')), 'hex');
  INSERT INTO reg.artifact(artifact_id, workspace_id, project_id, kind, semantic_name)
  VALUES (gen_random_uuid(), NULL, p_project_id, 'application', 'Project Application')
  ON CONFLICT ON CONSTRAINT artifact_project_id_kind_key DO NOTHING;

  SELECT * INTO STRICT artifact_row
  FROM reg.artifact AS stored_artifact
  WHERE stored_artifact.project_id = p_project_id
    AND stored_artifact.kind = 'application'
  FOR UPDATE;

  INSERT INTO reg.artifact_revision(
    artifact_revision_id, artifact_id, source_revision, digest, payload, availability
  ) VALUES (
    gen_random_uuid(), artifact_row.artifact_id, p_source_revision, computed_digest, p_payload, 'AVAILABLE'
  ) ON CONFLICT ON CONSTRAINT artifact_revision_artifact_id_source_revision_key DO NOTHING;

  SELECT * INTO STRICT revision_row
  FROM reg.artifact_revision AS stored_revision
  WHERE stored_revision.artifact_id = artifact_row.artifact_id
    AND stored_revision.source_revision = p_source_revision
  FOR SHARE;

  IF revision_row.digest IS DISTINCT FROM computed_digest OR revision_row.payload IS DISTINCT FROM p_payload
    OR revision_row.availability IS DISTINCT FROM 'AVAILABLE' THEN
    RAISE EXCEPTION 'APPLICATION_IDENTITY_CONFLICT' USING ERRCODE = 'P0001';
  END IF;

  RETURN QUERY SELECT revision_row.artifact_revision_id, revision_row.digest, artifact_row.project_id,
    revision_row.source_revision, revision_row.payload->>'profile', revision_row.payload->>'templateRef',
    revision_row.payload->>'recipeSha256', revision_row.payload->>'entryPath',
    (SELECT jsonb_agg(jsonb_build_object(
      'path', value->>'path', 'mediaType', value->>'mediaType',
      'byteLength', (value->>'byteLength')::integer, 'sha256', value->>'sha256'
    ) ORDER BY value->>'path' COLLATE "C") FROM jsonb_array_elements(revision_row.payload->'files') AS values(value));
END;
$_$;

ALTER FUNCTION reg.retain_application_execution(p_account_id uuid, p_project_id uuid, p_execution_id uuid, p_source_revision text, p_payload jsonb) OWNER TO registry_owner;

CREATE FUNCTION workspace.complete_create_workspace_receipt(p_account_id uuid, p_key_digest text, p_response_status integer, p_response_digest text, p_response_body jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  UPDATE workspace.operation_idempotency
  SET outcome = 'SUCCEEDED', response_status = p_response_status,
      response_digest = p_response_digest, response_body = p_response_body,
      completed_at = clock_timestamp()
  WHERE operation_id = 'WS-01' AND account_id = p_account_id
    AND key_digest = p_key_digest AND outcome = 'RESERVED';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'WS01_RECEIPT_NOT_RESERVED' USING ERRCODE = 'P0001';
  END IF;
END;
$$;

ALTER FUNCTION workspace.complete_create_workspace_receipt(p_account_id uuid, p_key_digest text, p_response_status integer, p_response_digest text, p_response_body jsonb) OWNER TO workspace_owner;

CREATE FUNCTION workspace.create_workspace(p_workspace_id uuid, p_name text, p_creator_account_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO workspace.workspace (workspace_id, name) VALUES (p_workspace_id, p_name);
  PERFORM iam.establish_workspace_creator_access(p_creator_account_id, p_workspace_id);
END;
$$;

ALTER FUNCTION workspace.create_workspace(p_workspace_id uuid, p_name text, p_creator_account_id uuid) OWNER TO workspace_owner;

CREATE FUNCTION workspace.get_workspace_summary(p_account_id uuid, p_workspace_id uuid) RETURNS TABLE(workspace_id uuid, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT stored_workspace.workspace_id, stored_workspace.name
  FROM workspace.workspace AS stored_workspace
  JOIN iam.visible_workspaces(p_account_id) AS visible
    ON visible.workspace_id = stored_workspace.workspace_id
  WHERE stored_workspace.workspace_id = p_workspace_id;
$$;

ALTER FUNCTION workspace.get_workspace_summary(p_account_id uuid, p_workspace_id uuid) OWNER TO workspace_owner;

CREATE FUNCTION workspace.list_visible_workspace_summaries(p_account_id uuid) RETURNS TABLE(workspace_id uuid, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT stored_workspace.workspace_id, stored_workspace.name
  FROM workspace.workspace AS stored_workspace
  JOIN iam.visible_workspaces(p_account_id) AS visible
    ON visible.workspace_id = stored_workspace.workspace_id;
$$;

ALTER FUNCTION workspace.list_visible_workspace_summaries(p_account_id uuid) OWNER TO workspace_owner;

CREATE FUNCTION workspace.reserve_or_replay_create_workspace(p_account_id uuid, p_key_digest text, p_request_digest text, p_candidate_workspace_id uuid) RETURNS TABLE(state text, workspace_id uuid, response_status integer, response_body jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  receipt workspace.operation_idempotency%ROWTYPE;
BEGIN
  INSERT INTO workspace.operation_idempotency (
    operation_id, account_id, key_digest, request_digest, reserved_workspace_id, outcome
  ) VALUES (
    'WS-01', p_account_id, p_key_digest, p_request_digest, p_candidate_workspace_id, 'RESERVED'
  ) ON CONFLICT (operation_id, account_id, key_digest) DO NOTHING;

  SELECT * INTO STRICT receipt
  FROM workspace.operation_idempotency AS operation_receipt
  WHERE operation_receipt.operation_id = 'WS-01'
    AND operation_receipt.account_id = p_account_id
    AND operation_receipt.key_digest = p_key_digest
  FOR UPDATE;

  IF receipt.request_digest <> p_request_digest THEN
    RETURN QUERY SELECT 'CONFLICT'::text, receipt.reserved_workspace_id, NULL::integer, NULL::jsonb;
  ELSIF receipt.outcome = 'SUCCEEDED' THEN
    RETURN QUERY SELECT 'REPLAY'::text, receipt.reserved_workspace_id, receipt.response_status, receipt.response_body;
  ELSE
    RETURN QUERY SELECT 'RESERVED'::text, receipt.reserved_workspace_id, NULL::integer, NULL::jsonb;
  END IF;
END;
$$;

ALTER FUNCTION workspace.reserve_or_replay_create_workspace(p_account_id uuid, p_key_digest text, p_request_digest text, p_candidate_workspace_id uuid) OWNER TO workspace_owner;

SET default_tablespace = '';

SET default_table_access_method = heap;

CREATE TABLE builder.builder_run (
    builder_run_id uuid NOT NULL,
    project_id uuid NOT NULL,
    account_id uuid NOT NULL,
    trigger_message_id text,
    idempotency_digest text NOT NULL,
    mode text NOT NULL,
    base_source_revision text NOT NULL,
    expected_working_version bigint NOT NULL,
    state text DEFAULT 'QUEUED'::text NOT NULL,
    result_source_revision text,
    result_kind text,
    sandbox_id text,
    failure_code text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    request_digest text NOT NULL,
    base_working_version bigint NOT NULL,
    model_admission_id text,
    model_provider_id text,
    model_id text,
    model_connection_id uuid,
    model_credential_generation bigint,
    cancellation_requested_at timestamp with time zone,
    cancellation_reason text,
    phase text,
    CONSTRAINT builder_run_base_source_revision_check CHECK ((base_source_revision ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT builder_run_base_working_version_check CHECK ((base_working_version >= 0)),
    CONSTRAINT builder_run_expected_working_version_check CHECK ((expected_working_version >= 0)),
    CONSTRAINT builder_run_idempotency_digest_check CHECK ((idempotency_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT builder_run_mode_check CHECK ((mode = ANY (ARRAY['BUILD'::text, 'PLAN'::text]))),
    CONSTRAINT builder_run_model_snapshot_check CHECK (((model_connection_id IS NULL) = (model_credential_generation IS NULL))),
    CONSTRAINT builder_run_phase_check CHECK (((phase IS NULL) OR ((state = 'RUNNING'::text) AND (cancellation_requested_at IS NULL) AND (phase = ANY (ARRAY['PREPARING'::text, 'AGENT'::text, 'SOURCE_ADMISSION'::text, 'COMPILING'::text, 'FINALIZING'::text]))))),
    CONSTRAINT builder_run_request_digest_check CHECK ((request_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT builder_run_result_kind_check CHECK (((result_kind IS NULL) OR (result_kind = ANY (ARRAY['RESPONSE_ONLY'::text, 'SOURCE_CHANGED'::text, 'SOURCE_CHANGED_BUILD_FAILED'::text])))),
    CONSTRAINT builder_run_result_source_revision_check CHECK (((result_source_revision IS NULL) OR (result_source_revision ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT builder_run_state_check CHECK ((state = ANY (ARRAY['QUEUED'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'INTERRUPTED'::text]))),
    CONSTRAINT builder_run_trigger_message_id_check CHECK (((length(btrim(trigger_message_id)) >= 1) AND (length(btrim(trigger_message_id)) <= 200)))
);

ALTER TABLE builder.builder_run OWNER TO builder_owner;

CREATE TABLE builder.project_working_state (
