    working_source_revision text NOT NULL,
    working_version bigint DEFAULT 0 NOT NULL,
    current_state text DEFAULT 'IDLE'::text NOT NULL,
    last_preview_source_revision text,
    last_preview_artifact_revision_id uuid,
    last_preview_artifact_digest text,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT project_working_state_current_state_check CHECK ((current_state = ANY (ARRAY['IDLE'::text, 'CODING'::text, 'PREPARING'::text, 'PREVIEW_READY'::text, 'BUILD_FAILED'::text, 'RESPONDED'::text]))),
    CONSTRAINT project_working_state_last_preview_artifact_digest_check CHECK (((last_preview_artifact_digest IS NULL) OR (last_preview_artifact_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT project_working_state_last_preview_source_revision_check CHECK (((last_preview_source_revision IS NULL) OR (last_preview_source_revision ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT project_working_state_preview_coordinates_check CHECK ((((last_preview_source_revision IS NULL) = (last_preview_artifact_revision_id IS NULL)) AND ((last_preview_source_revision IS NULL) = (last_preview_artifact_digest IS NULL)))),
    CONSTRAINT project_working_state_working_source_revision_check CHECK ((working_source_revision ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT project_working_state_working_version_check CHECK ((working_version >= 0))
);

ALTER TABLE builder.project_working_state OWNER TO builder_owner;

CREATE TABLE iam.account (
