    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT account_display_name_check CHECK ((display_name ~ '\S'::text)),
    CONSTRAINT account_external_subject_check CHECK ((external_subject <> ''::text)),
    CONSTRAINT account_issuer_check CHECK ((issuer <> ''::text))
);

ALTER TABLE iam.account OWNER TO iam_owner;

