    request_digest bytea NOT NULL,
    outcome text NOT NULL,
    response_status integer,
    response_body jsonb,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT operation_idempotency_operation_id_check CHECK ((operation_id = 'IAM-03'::text)),
    CONSTRAINT operation_idempotency_outcome_check CHECK ((outcome = ANY (ARRAY['RESERVED'::text, 'SUCCEEDED'::text])))
);

ALTER TABLE iam.operation_idempotency OWNER TO iam_owner;

CREATE TABLE iam.schema_migration (
    version text NOT NULL,
