    CONSTRAINT authorization_pkce_verifier_check CHECK (((length(pkce_verifier) >= 43) AND (length(pkce_verifier) <= 128))),
    CONSTRAINT authorization_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'EXCHANGING'::text, 'COMPLETED'::text, 'FAILED'::text])))
);

ALTER TABLE model_connection."authorization" OWNER TO model_connection_owner;

CREATE TABLE model_connection.connection (
