    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    revoked_at timestamp with time zone,
    provider_id text NOT NULL,
    credential_kind text NOT NULL,
    CONSTRAINT connection_credential_kind_check CHECK ((credential_kind = ANY (ARRAY['OAUTH_TOKEN_SET'::text, 'API_KEY'::text]))),
    CONSTRAINT connection_current_generation_check CHECK ((current_generation > 0)),
    CONSTRAINT connection_label_check CHECK (((label ~ '[^[:space:]]'::text) AND (length(label) <= 120))),
    CONSTRAINT connection_provider_id_check CHECK ((provider_id ~ '^[a-z0-9][a-z0-9._-]{0,127}$'::text)),
    CONSTRAINT connection_state_check CHECK ((state = ANY (ARRAY['ACTIVE'::text, 'REVOKED'::text])))
);

ALTER TABLE model_connection.connection OWNER TO model_connection_owner;

