CREATE TABLE project.operation_idempotency (
    operation_id text NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    key_digest text NOT NULL,
    request_digest text NOT NULL,
    reserved_project_id uuid NOT NULL,
    outcome text NOT NULL,
    response_status integer,
    response_digest text,
    response_body jsonb,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT operation_idempotency_check CHECK ((((outcome = 'RESERVED'::text) AND (response_status IS NULL) AND (response_digest IS NULL) AND (response_body IS NULL) AND (completed_at IS NULL)) OR ((outcome = 'SUCCEEDED'::text) AND (response_status IS NOT NULL) AND (response_digest IS NOT NULL) AND (response_body IS NOT NULL) AND (completed_at IS NOT NULL)))),
    CONSTRAINT operation_idempotency_key_digest_check CHECK ((key_digest ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT operation_idempotency_operation_id_check CHECK ((operation_id = 'PRJ-03'::text)),
    CONSTRAINT operation_idempotency_outcome_check CHECK ((outcome = ANY (ARRAY['RESERVED'::text, 'SUCCEEDED'::text]))),
    CONSTRAINT operation_idempotency_request_digest_check CHECK ((request_digest ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT operation_idempotency_response_digest_check CHECK ((response_digest ~ '^[a-f0-9]{64}$'::text))
);

ALTER TABLE project.operation_idempotency OWNER TO project_owner;

