    CONSTRAINT project_name_check CHECK ((name ~ '\S'::text)),
    CONSTRAINT project_project_revision_check CHECK ((project_revision ~ '\S'::text)),
    CONSTRAINT project_source_mode_check CHECK ((source_mode = ANY (ARRAY['NEW'::text, 'EXISTING_GIT'::text]))),
