    published_revision_id uuid,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    project_id uuid,
    CONSTRAINT artifact_kind_check CHECK ((kind = ANY (ARRAY['brain'::text, 'application'::text]))),
    CONSTRAINT artifact_kind_ownership_check CHECK ((((kind = 'brain'::text) AND (workspace_id IS NOT NULL) AND (project_id IS NULL)) OR ((kind = 'application'::text) AND (workspace_id IS NULL) AND (project_id IS NOT NULL) AND (published_revision_id IS NULL)))),
    CONSTRAINT artifact_semantic_name_check CHECK ((semantic_name ~ '\S'::text))
);

ALTER TABLE reg.artifact OWNER TO registry_owner;

